class Solution {
    public int findLongestChain(int[][] pairs) {
        java.util.Arrays.sort(pairs, (a, b) -> Integer.compare(a[1], b[1]));

        int count = 0;
        int currentEnd = Integer.MIN_VALUE;
        for (int[] pair : pairs) {
            if (pair[0] > currentEnd) {
                count++;
                currentEnd = pair[1];
            }
        }
        return count;
    }
}

class Solution {
    public int findLongestChain(int[][] pairs) {
        java.util.Arrays.sort(pairs, (a, b) -> Integer.compare(a[0], b[0]));

        int n = pairs.length;
        int[] dp = new int[n];
        java.util.Arrays.fill(dp, 1);
        int best = 1;

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (pairs[j][1] < pairs[i][0]) {
                    dp[i] = Math.max(dp[i], dp[j] + 1);
                }
            }
            best = Math.max(best, dp[i]);
        }
        return best;
    }
}

class Solution {
    public int findLongestChain(int[][] pairs) {
        java.util.Arrays.sort(pairs, (a, b) -> {
            if (a[0] != b[0]) {
                return Integer.compare(a[0], b[0]);
            }
            return Integer.compare(a[1], b[1]);
        });

        int[] tails = new int[pairs.length];
        int length = 0;
        for (int[] pair : pairs) {
            int lo = 0;
            int hi = length;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails[mid] < pair[0]) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }

            if (lo == length) {
                tails[length++] = pair[1];
            } else if (pair[1] < tails[lo]) {
                tails[lo] = pair[1];
            }
        }
        return length;
    }
}
